<?php
require_once 'config/app.php';require_roles(['admin','operator','pimpinan']);$pageTitle='Laporan';
$from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-d');$export=$_GET['export']??'';
$sql="SELECT p.*,g.nama,g.nip,k.merk,k.nomor_polisi FROM peminjaman p JOIN pegawai g ON g.id=p.pegawai_id JOIN kendaraan k ON k.id=p.kendaraan_id WHERE DATE(p.tanggal_pinjam) BETWEEN ? AND ? ORDER BY p.tanggal_pinjam DESC";$q=$pdo->prepare($sql);$q->execute([$from,$to]);$rows=$q->fetchAll();
if($export==='csv'){header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename=laporan_silanjo_'.$from.'_'.$to.'.csv');$out=fopen('php://output','w');fwrite($out,"\xEF\xBB\xBF");fputcsv($out,['Nomor Pengajuan','Nama Peminjam','NIP','Kendaraan','Nomor Polisi','Tanggal Pinjam','Rencana Kembali','Tujuan','Status']);foreach($rows as $r)fputcsv($out,[$r['nomor_peminjaman'],$r['nama'],$r['nip'],$r['merk'],$r['nomor_polisi'],$r['tanggal_pinjam'],$r['tanggal_kembali_rencana'],$r['tujuan'],$r['status']]);fclose($out);exit;}
require 'includes/header.php';?>
<div class="d-flex justify-content-between mb-3"><h3>Laporan Peminjaman</h3></div><div class="card mb-3"><div class="card-body"><form class="row g-2 align-items-end"><div class="col-md-3"><label class="form-label">Dari tanggal</label><input type="date" name="from" value="<?=e($from)?>" class="form-control"></div><div class="col-md-3"><label class="form-label">Sampai tanggal</label><input type="date" name="to" value="<?=e($to)?>" class="form-control"></div><div class="col-md-6"><button class="btn btn-primary">Tampilkan</button> <a class="btn btn-success" href="?from=<?=e($from)?>&to=<?=e($to)?>&export=csv">Export Excel (CSV)</a> <button type="button" onclick="window.print()" class="btn btn-outline-secondary">Cetak / Simpan PDF</button></div></form></div></div><div class="card"><div class="card-header bg-white">Periode <?=e(date('d-m-Y',strtotime($from)))?> s.d. <?=e(date('d-m-Y',strtotime($to)))?> · <?=count($rows)?> transaksi</div><div class="table-responsive"><table class="table table-striped mb-0"><thead><tr><th>No.</th><th>Peminjam</th><th>Kendaraan</th><th>Tanggal Pinjam</th><th>Rencana Kembali</th><th>Tujuan</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $i=>$r):?><tr><td><?=e($r['nomor_peminjaman'])?></td><td><?=e($r['nama'])?></td><td><?=e($r['merk'].' / '.$r['nomor_polisi'])?></td><td><?=e(date('d-m-Y H:i',strtotime($r['tanggal_pinjam'])))?></td><td><?=e(date('d-m-Y H:i',strtotime($r['tanggal_kembali_rencana'])))?></td><td><?=e($r['tujuan'])?></td><td><?=status_badge($r['status'])?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="7" class="text-center p-4">Tidak ada data pada periode ini.</td></tr><?php endif;?></tbody></table></div></div><?php require 'includes/footer.php';?>